'use client';

import { ark, type HTMLArkProps } from '@ark-ui/react/factory';
import {
  HoverCard as HoverCardPrimitive,
  useHoverCard,
  useHoverCardContext,
} from '@ark-ui/react/hover-card';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import styles from './HoverCard.module.css';

type HoverCardRootProps = ComponentProps<typeof HoverCardPrimitive.Root> & OverlayPortalProps;
type HoverCardRootProviderProps = ComponentProps<typeof HoverCardPrimitive.RootProvider> &
  OverlayPortalProps;

function HoverCard({
  lazyMount = true,
  portalled,
  portalRef,
  unmountOnExit = true,
  ...props
}: HoverCardRootProps) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <HoverCardPrimitive.Root lazyMount={lazyMount} unmountOnExit={unmountOnExit} {...props} />
    </OverlayPortalProvider>
  );
}

function HoverCardRootProvider({
  lazyMount = true,
  portalled,
  portalRef,
  unmountOnExit = true,
  ...props
}: HoverCardRootProviderProps) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <HoverCardPrimitive.RootProvider
        lazyMount={lazyMount}
        unmountOnExit={unmountOnExit}
        {...props}
      />
    </OverlayPortalProvider>
  );
}

const HoverCardTrigger = forwardRef<
  ComponentRef<typeof HoverCardPrimitive.Trigger>,
  ComponentProps<typeof HoverCardPrimitive.Trigger>
>(function HoverCardTrigger({ asChild, className, ...props }, ref) {
  return (
    <HoverCardPrimitive.Trigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.trigger, className)}
      {...props}
      data-slot="hover-card-trigger"
    />
  );
});

const HoverCardPositioner = forwardRef<
  ComponentRef<typeof HoverCardPrimitive.Positioner>,
  ComponentProps<typeof HoverCardPrimitive.Positioner>
>(function HoverCardPositioner({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <HoverCardPrimitive.Positioner
        ref={ref}
        className={clsx(styles.positioner, className)}
        {...props}
        data-slot="hover-card-positioner"
      />
    </OverlayPortal>
  );
});

const HoverCardContent = forwardRef<
  ComponentRef<typeof HoverCardPrimitive.Content>,
  ComponentProps<typeof HoverCardPrimitive.Content>
>(function HoverCardContent({ className, ...props }, ref) {
  return (
    <HoverCardPrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="hover-card-content"
    />
  );
});

const HoverCardArrow = forwardRef<
  ComponentRef<typeof HoverCardPrimitive.Arrow>,
  ComponentProps<typeof HoverCardPrimitive.Arrow>
>(function HoverCardArrow({ className, children, ...props }, ref) {
  return (
    <HoverCardPrimitive.Arrow
      ref={ref}
      className={clsx(styles.arrow, className)}
      {...props}
      data-slot="hover-card-arrow"
    >
      {children ?? <HoverCardArrowTip />}
    </HoverCardPrimitive.Arrow>
  );
});

const HoverCardArrowTip = forwardRef<
  ComponentRef<typeof HoverCardPrimitive.ArrowTip>,
  ComponentProps<typeof HoverCardPrimitive.ArrowTip>
>(function HoverCardArrowTip({ className, ...props }, ref) {
  return (
    <HoverCardPrimitive.ArrowTip
      ref={ref}
      className={clsx(styles.arrowTip, className)}
      {...props}
      data-slot="hover-card-arrow-tip"
    />
  );
});

const HoverCardBody = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function HoverCardBody({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.body, className)}
        {...props}
        data-slot="hover-card-body"
      />
    );
  },
);

const HoverCardContext = HoverCardPrimitive.Context;

export {
  HoverCard,
  HoverCardArrow,
  HoverCardArrowTip,
  HoverCardBody,
  HoverCardContent,
  HoverCardContext,
  HoverCardPositioner,
  HoverCardRootProvider,
  HoverCardTrigger,
  useHoverCard,
  useHoverCardContext,
  type HoverCardRootProps,
  type HoverCardRootProviderProps,
};

export type {
  HoverCardArrowProps,
  HoverCardArrowTipProps,
  HoverCardContentProps,
  HoverCardContextProps,
  HoverCardFocusOutsideEvent,
  HoverCardInteractOutsideEvent,
  HoverCardOpenChangeDetails,
  HoverCardPointerDownOutsideEvent,
  HoverCardPositionerProps,
  HoverCardTriggerProps,
  HoverCardTriggerValueChangeDetails,
  UseHoverCardContext,
  UseHoverCardProps,
  UseHoverCardReturn,
} from '@ark-ui/react/hover-card';

@layer moduix.components {
  .trigger {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-spacing-1);
    outline: 0;
    color: var(--moduix-color-primary);
    font: inherit;
    text-decoration-line: underline;
    text-decoration-thickness: 1px;
    text-decoration-color: color-mix(in oklab, currentColor, transparent 40%);
    text-underline-offset: 2px;
    cursor: pointer;
    transition: text-decoration-color var(--moduix-transition-fast);

    @media (hover: hover) {
      &:hover {
        text-decoration-color: currentColor;
      }
    }

    &[data-state='open'] {
      text-decoration-color: currentColor;
    }

    &:focus-visible {
      border-radius: var(--moduix-radius-xs);
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-offset);
      text-decoration-line: none;
    }

    &:disabled {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .positioner {
    z-index: var(--z-index, var(--moduix-z-popup));
    max-width: var(--available-width);
    outline: 0;
  }

  .content {
    position: relative;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    box-sizing: border-box;
    min-width: min(14rem, var(--available-width));
    max-width: min(24rem, var(--available-width));
    max-height: min(24rem, var(--available-height, 100dvh));
    overflow-wrap: anywhere;
    padding: var(--moduix-spacing-2);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    outline: 0;
    box-shadow: var(--moduix-shadow-lg);
    transform-origin: var(--transform-origin);

    /* Lets HoverCardBody scroll within the height limit while the surface stays overflow-visible for the arrow. */
    &:has(> .body) {
      display: flex;
      flex-direction: column;
    }

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }
  }

  .body {
    min-block-size: 0;
    overflow: auto;
  }

  .arrow {
    --arrow-size: var(--moduix-spacing-2-5);
    --arrow-background: var(--moduix-color-popover);
    --arrow-shadow-color: var(--moduix-color-border);
  }

  .arrowTip {
    border-top: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-left: var(--moduix-border-width-sm) solid var(--moduix-color-border);
  }

  @media (prefers-reduced-motion: reduce) {
    .trigger {
      transition: none;
    }

    .content[data-state] {
      animation: none;
    }
  }
}
